import { useEffect, useState } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { verifyInviteCode, acceptInvite, signIn, markInviteAccepted } from '../services/authService'
import AuthLayout from '../components/shared/AuthLayout'
import Alert from '../components/ui/Alert'
import Button from '../components/ui/Button'
import { Input } from '../components/ui/Field'
import { FullPageLoader } from '../components/ui/Loading'

// :token is the oobCode from the invite link generated by inviteStaff.js
// (admin.auth().generatePasswordResetLink). Firebase itself rejects an
// expired or already-used code, so that's what drives the error state below
// rather than a separate Firestore "used" lookup.
function AcceptInvitePage() {
  const { token } = useParams()
  const navigate = useNavigate()
  const [email, setEmail] = useState(null)
  const [checking, setChecking] = useState(true)
  const [tokenError, setTokenError] = useState(null)
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [formError, setFormError] = useState(null)

  useEffect(() => {
    let cancelled = false
    async function checkToken() {
      try {
        const invitedEmail = await verifyInviteCode(token)
        if (!cancelled) setEmail(invitedEmail)
      } catch (err) {
        if (!cancelled) {
          setTokenError(
            err.code === 'auth/expired-action-code' || err.code === 'auth/invalid-action-code'
              ? 'This invite link has expired or has already been used. Ask your Company Admin to send a new one.'
              : 'This invite link is not valid.'
          )
        }
      } finally {
        if (!cancelled) setChecking(false)
      }
    }
    checkToken()
    return () => {
      cancelled = true
    }
  }, [token])

  async function handleSubmit(e) {
    e.preventDefault()
    setFormError(null)
    if (password.length < 8) {
      setFormError('Password must be at least 8 characters')
      return
    }
    if (password !== confirmPassword) {
      setFormError('Passwords do not match')
      return
    }
    setSubmitting(true)
    try {
      await acceptInvite(token, password)
      // Invites only ever create company staff (never a super admin - that
      // account type is created directly by Lumora), so this always lands
      // on the staff dashboard.
      await signIn(email, password)
      await markInviteAccepted()
      navigate('/dashboard', { replace: true })
    } catch {
      setFormError('Could not set your password. Please try again.')
    } finally {
      setSubmitting(false)
    }
  }

  if (checking) {
    return <FullPageLoader label="Checking your invite" />
  }

  if (tokenError) {
    return (
      <AuthLayout
        title="Invite not available"
        footer={
          <Link to="/login" className="font-medium text-navy hover:underline">
            Go to sign in
          </Link>
        }
      >
        <Alert variant="error" title="This link cannot be used">
          {tokenError}
        </Alert>
      </AuthLayout>
    )
  }

  return (
    <AuthLayout
      title="Set up your account"
      description="Choose a password and you're in."
    >
      <form onSubmit={handleSubmit} className="card flex flex-col gap-4 p-6">
        <Input label="Your email" type="email" value={email ?? ''} readOnly disabled />
        <Input
          label="Choose a password"
          type="password"
          required
          autoComplete="new-password"
          placeholder="At least 8 characters"
          hint="Use at least 8 characters."
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <Input
          label="Confirm password"
          type="password"
          required
          autoComplete="new-password"
          placeholder="Re-enter your password"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
        />

        {formError && <Alert variant="error">{formError}</Alert>}

        <Button
          type="submit"
          variant="primary"
          size="lg"
          className="w-full"
          loading={submitting}
          loadingLabel="Setting up"
        >
          Set password and continue
        </Button>
      </form>
    </AuthLayout>
  )
}

export default AcceptInvitePage
